fr.exercice_solution:
@Composable
fun ReminderScreen() {
    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(16.dp)
    ) {
        // Row avec trois boutons
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(8.dp),
            horizontalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            Button(
                onClick = { /* Gérer clic bouton 1 */ },
                modifier = Modifier.weight(1f)
            ) {
                Text("Bouton 1")
            }
            Button(
                onClick = { /* Gérer clic bouton 2 */ },
                modifier = Modifier.weight(1f)
            ) {
                Text("Bouton 2")
            }
            Button(
                onClick = { /* Gérer clic bouton 3 */ },
                modifier = Modifier.weight(1f)
            ) {
                Text("Bouton 3")
            }
        }

        // Column avec deux Textes
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(8.dp)
        ) {
            Text(
                text = "Titre du rappel",
                style = MaterialTheme.typography.h6
            )
            Text(
                text = "Description du rappel",
                style = MaterialTheme.typography.body1
            )
        }

        // Box avec label rouge en haut à droite
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .padding(8.dp)
        ) {
            Text(
                text = "URGENT",
                modifier = Modifier
                    .align(Alignment.TopEnd)
                    .background(Color.Red, RoundedCornerShape(4.dp))
                    .padding(horizontal = 8.dp, vertical = 4.dp),
                color = Color.White,
                style = MaterialTheme.typography.body2
            )
        }
    }
}

